  bcrypt.hash('password123', 12).then(hashedPassword => {
    users['demo'] = {
      login: 'demo',
      hashedPassword: hashedPassword
    };
    messages['demo'] = [
      {
        id: 1,
        sender: 'admin',
        content: 'Welcome to BlueMind v5! This is a sample message.',
        timestamp: new Date().toISOString()
      },
      {
